script:
frappe.ui.form.on('Lorry Hire Challan', {
    total_weight: function(frm) {
        calculate_hire(frm);
    },
    hire_rate: function(frm) {
        calculate_hire(frm);
    }
});

function calculate_hire(frm) {
    if (frm.doc.total_weight && frm.doc.hire_rate) {
        let calculated_amount = frm.doc.total_weight * frm.doc.hire_rate;
        frm.set_value('lorry_hire_amount', calculated_amount);
    }
}

frappe.ui.form.on("Sales Invoice", {
    refresh(frm) {
        if (!frm.is_new()) return;

        frm.add_custom_button("Fetch Consignment Notes", () => {
            frappe.prompt([
                {
                    label: "Customer",
                    fieldname: "customer",
                    fieldtype: "Link",
                    options: "Customer",
                    reqd: 1
                }
            ], (values) => {
                fetch_consignment_notes(frm, values.customer);
            });
        });
    }
});

function fetch_consignment_notes(frm, customer) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Consignment Note",
            filters: {
                customer: customer,
                invoiced: 0
            },
            fields: ["name", "posting_date", "route", "freight_amount"]
        },
        callback: function(r) {
            if (!r.message) return;

            frm.clear_table("consignment_notes");

            let total = 0;

            r.message.forEach(cn => {
                let row = frm.add_child("consignment_notes");
                row.consignment_note = cn.name;
                row.consignment_date = cn.posting_date;
                row.route = cn.route;
                row.freight_amount = cn.freight_amount;

                total += cn.freight_amount;
            });

            frm.set_value("items", []);
            frm.add_child("items", {
                item_code: "Freight Charges",
                qty: 1,
                rate: total
            });

            frm.refresh_fields();
        }
    });
}

frappe.ui.form.on("Sales Invoice", {
    onload: function(frm) {
        frm.set_query(
            "consignment_note",
            "custom_list_of_consignments",
            function() {
                return {
                    filters: {
                        invoiced: 0
                    }
                };
            }
        );
    }
});

function calculate_totals(frm) {
    let total_packages = 0;
    let total_charged_weight = 0;

    // ✅ Existing logic (DO NOT CHANGE)
    (frm.doc.good_details || []).forEach(row => {
        total_packages += flt(row.packages);
        total_charged_weight += flt(row.charged_weight);
    });

    frm.set_value("total_packages", total_packages);
    frm.set_value("total_charged_weight", total_charged_weight);

    // ✅ NEW: use already-calculated total_charged_weight
    let rate = flt(frm.doc.rate);
    let extra = flt(frm.doc.extra_charges);

    let freight_amount = total_charged_weight * rate;
    let total_amount = freight_amount + extra;

    frm.set_value("total_amount", total_amount);
}

// ===============================
// Child table triggers (unchanged)
// ===============================
frappe.ui.form.on("Consignment Item", {
    packages:function(frm) {
        calculate_totals(frm);
    },
    charged_weight:function(frm) {
        calculate_totals(frm);
    },
    good_details_remove:function(frm) {
        calculate_totals(frm);
    }
});

// ===============================
// Parent DocType triggers
// ===============================
frappe.ui.form.on("Consignment Note", {
    refresh:function(frm) {
        calculate_totals(frm);
    },
    rate:function(frm) {
        calculate_totals(frm);
    },
    extra_charges:function(frm) {
        calculate_totals(frm);
    }
});

function calculate_total_freight_and_weight(frm) {
    let total_amount = 0;
    let total_weight = 0;

    (frm.doc.consignments || []).forEach(row => {
        total_amount += flt(row.freight_amount);
        total_weight += flt(row.total_weight);
    });

    frm.set_value("custom_total_amount", total_amount);
    frm.set_value("custom_total_weight", total_weight);
}

// ===============================
// Child Table Logic
// ===============================
frappe.ui.form.on("Sales Invoice Consignment", {
    consignment_note(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (row.consignment_note) {
            frappe.db.get_value(
                "Consignment Note",
                row.consignment_note,
                ["total_amount", "total_charged_weight"],
                (r) => {
                    // Set values in child row
                    row.freight_amount = r.total_amount || 0;
                    row.total_weight = r.total_charged_weight || 0;

                    frm.refresh_field("consignments");
                    calculate_total_freight_and_weight(frm);
                }
            );
        }
    },

    consignments_remove(frm) {
        calculate_total_freight_and_weight(frm);
    }
});

// ===============================
// Parent DocType Logic
// ===============================
frappe.ui.form.on("Sales Invoice", {
    refresh(frm) {
        calculate_total_freight_and_weight(frm);
    }
});
